const paths={inicio:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',avisos:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 20h4',refugios:'M12 22s8-9 8-14a8 8 0 1 0-16 0c0 5 8 14 8 14z M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',contactos:'M5 3h4l2 5-3 2q2 5 6 6l2-3 5 2v4q0 3-4 2Q4 18 3 6z',guia:'M3 5q5-2 9 1 4-3 9-1v14q-5-2-9 1-4-3-9-1z M12 6v14',coord:'M4 5h16v16H4z M8 9h8 M8 13h8 M8 17h5'};
const icon=k=>'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"><path d="'+paths[k]+'"/></svg>';
const labels={inicio:'Inicio',avisos:'Avisos',refugios:'Refugios',contactos:'Contactos'};
const towns=['San Pedro Cholula','Atempan'];
const places=[
['Refugio temporal de Cholula','Av. 14 Poniente 307, Centro',0,'Abierto','Rampa de entrada y sanitarios accesibles.'],
['Refugio Deportivo Santiago','Calle 9 Norte s/n, Barrio de Santiago',0,'Abierto','Accesibilidad pendiente de confirmar.'],
['Auditorio Municipal','Palacio Municipal',1,'Abierto','Acceso verificado en el ejercicio. Capacidad nominal de 500 personas.'],
['Esc. 1º de enero','2 Sur y 3 Oriente',1,'Acceso bloqueado','Capacidad nominal de 300 personas.'],
['Esc. Manuel Acuña Hernández','Av. Benito Juárez 147, Tacopan',1,'Sin confirmar','Capacidad nominal de 250 personas.']];
let town=0,mode='mapa',zoom=1,incident=null;
try{incident=JSON.parse(localStorage.getItem('sicep.demo.v1'))}catch{}
const app=document.querySelector('#app');
const select=()=>'<label>Municipio<select id="town">'+towns.map((t,i)=>'<option value="'+i+'" '+(i===town?'selected':'')+'>'+t+'</option>').join('')+'</select></label>';
const tile=(k,title,sub)=>'<a class="tile" href="#'+k+'"><span class="icon">'+icon(k)+'</span><div><b>'+title+'</b><span class="muted">'+sub+'</span></div><span class="chev">›</span></a>';
const back=(k='inicio',label='Inicio')=>'<a class="link back" href="#'+k+'">‹ '+label+'</a>';
const pill=p=>'<span class="pill '+(p==='Abierto'?'':'neutral')+'">'+p+'</span>';
function home(){return '<section class="hero"><article><small>Protección civil · Puebla</small><h1>Bienvenida, bienvenido a SICEP Puebla</h1><p>Información para tu seguridad y la de tu comunidad.</p></article><img src="assets/cholula.png" alt="Ilustración del Popocatépetl y el santuario de Cholula"></section><div class="grid"><section class="card"><h2>Encuentra un refugio</h2><p>Consulta los refugios temporales de tu municipio.</p><div class="controls">'+select()+'<a class="btn" href="#refugios">'+icon('inicio')+' Buscar refugio</a></div></section><section class="card notice"><small>Aviso de simulación</small><h2>Actividad del Popocatépetl</h2><p>Semáforo de alerta volcánica del ejercicio <b>Amarillo Fase 2.</b></p><a class="link" href="#avisos">Consultar aviso</a></section></div><h2>Recursos de protección civil</h2><div class="tiles">'+tile('guia','Guía de preparación','Antes de una emergencia')+tile('contactos','Contactos','Directorio de emergencia')+tile('coord','Coordinación','Municipio y brigadas')+'</div>'}
function shelters(){let rows=places.map((p,i)=>p[2]===town?'<a class="row" href="#detalle/'+i+'"><span class="icon">'+icon('inicio')+'</span><div><b>'+p[0]+'</b><span class="muted">'+p[1]+'</span></div><span style="margin-left:auto">'+pill(p[3])+'</span></a>':'').join('');
return back()+'<small style="display:block">Directorio de demostración</small><h1>Refugios temporales</h1>'+select()+'<div class="segment">'+['mapa','lista'].map(m=>'<button data-mode="'+m+'" aria-pressed="'+(m===mode)+'">'+(m==='mapa'?'Mapa':'Lista')+'</button>').join('')+'</div>'+(mode==='mapa'?(town===0?'<div class="map"><div class="mapinner" style="transform:scale('+zoom+')">'+[[0,54,10],[1,17,46]].map(([i,x,y])=>'<a class="pin" href="#detalle/'+i+'" aria-label="'+places[i][0]+'" style="left:'+x+'%;top:'+y+'%"></a>').join('')+'</div><div class="zoom"><button data-zoom="1" aria-label="Acercar">+</button><button data-zoom="-1" aria-label="Alejar">−</button></div></div><span class="muted">Mapa ilustrativo · Selecciona un refugio.</span>':'<p class="card">Ubicaciones pendientes de verificar. Consulta las direcciones del directorio.</p>'):'')+'<h2 style="margin-top:16px">'+(town===0?2:3)+' refugios en '+towns[town]+'</h2><div class="stack">'+rows+'</div>'}
function detail(id){let p=places[id];if(!p)return shelters();town=p[2];return back('refugios','Refugios')+'<div>'+pill(p[3])+'</div><h1>'+p[0]+'</h1><div class="card"><h3>Dirección</h3><p>'+p[1]+', '+towns[town]+', Puebla.</p><h3>Acceso y capacidad</h3><p>'+p[4]+(id===2?' Cupo del ejercicio: '+(40-(incident?.stage>=2?incident.count:0))+'.':'')+'</p><h3>Última actualización</h3><p>Registro de demostración.</p></div><a class="btn" href="https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p[1]+', '+towns[town]+', Puebla, México')+'" target="_blank" rel="noopener">Cómo llegar · Google Maps</a><p class="muted">Dirección de ejemplo. Verifica la ubicación antes de trasladarte.</p>'}
const source='<a class="link" target="_blank" rel="noopener" href="https://proteccioncivil.puebla.gob.mx/">Protección Civil del Estado de Puebla</a>';
function coordination(){let stage=incident?.stage||0;return back()+'<small style="display:block">Simulación municipal · Atempan</small><h1>Coordinación de brigadas</h1><p>Practica la atención de una inundación. El ejercicio se guarda en este navegador.</p><div class="card">'+(!stage?'<form id="report"><h2>Registrar incidente</h2><p>Inundación en Atempan</p><label>Personas que necesitan alojamiento<input type="number" name="count" min="1" max="9999" value="35" required></label><button>Registrar y revisar propuesta</button></form>':'<small>Folio SICEP-AT-001</small><h2>Inundación en Atempan</h2><p>'+incident.count+' personas requieren alojamiento.</p>'+(stage===1?(incident.count<=40?'<h3>Propuesta · Auditorio Municipal</h3><p>El acceso está verificado y los 40 lugares del ejercicio cubren la solicitud. Los otros refugios tienen acceso bloqueado o pendiente de confirmar.</p><button data-step="2">Confirmar asignación a brigada</button>':'<p>Los 40 lugares disponibles son insuficientes. Se requiere coordinación adicional.</p>'):stage===2?'<h3>Asignación confirmada</h3><p>Brigada municipal: recibe la asignación al Auditorio Municipal para '+incident.count+' personas.</p><button data-step="3">Acusar recibo como brigada</button>':'<h3>Brigada enterada</h3><p>Acuse registrado para el Auditorio Municipal.</p>')+'<p><button class="segment" data-step="0">Reiniciar ejercicio</button></p>')+'</div>'}
function render(){let [page,id]=(location.hash.slice(1)||'inicio').split('/');document.querySelector('#nav').innerHTML=Object.entries(labels).map(([k,v])=>'<a class="'+(k===(page==='detalle'?'refugios':page)?'on':'')+'" href="#'+k+'">'+icon(k)+v+'</a>').join('');let content;
switch(page){case 'refugios':content=shelters();break;case 'detalle':content=detail(Number(id));break;case 'coord':content=coordination();break;case 'avisos':content=back()+'<h1>Avisos</h1><section class="card notice"><small>Aviso de demostración</small><h2>Actividad del Popocatépetl</h2><p>En este escenario, el semáforo volcánico está en Amarillo Fase 2. Para consultar el estado vigente y las indicaciones oficiales, visita el portal estatal.</p>'+source+'</section>';break;case 'contactos':content=back()+'<h1>Contactos de emergencia</h1><section class="card"><h2>Emergencias · 911</h2><p>Policía, bomberos y atención médica. Utiliza esta línea únicamente ante una emergencia real.</p><a class="btn" href="tel:911">'+icon('contactos')+' Llamar al 911</a></section><section class="card"><h2>Protección Civil</h2>'+source+'</section>';break;case 'guia':content=back()+'<h1>Guía de preparación</h1>'+[['Plan familiar','Acuerden un punto de encuentro y anoten los contactos de su red de apoyo.'],['Mochila de emergencia','Prepara agua, linterna, documentos y medicamentos personales.'],['Consulta de refugios','Selecciona tu municipio y revisa la dirección y el estado de cada refugio.']].map(([h,p])=>'<details class="card"><summary>'+h+'</summary><p>'+p+'</p></details>').join('')+'<a class="link" href="#refugios">Consultar refugios</a>';break;default:page='inicio';content=home()}
app.innerHTML=page==='inicio'?content:'<div class="sheet">'+content+'</div>';document.title=(labels[page]||'Protección civil')+' · SICEP Puebla'}
app.addEventListener('change',e=>{if(e.target.id==='town'){town=Number(e.target.value);zoom=1;render()}});
function save(){try{localStorage.setItem('sicep.demo.v1',JSON.stringify(incident))}catch{}render()}
app.addEventListener('submit',e=>{e.preventDefault();incident={stage:1,count:Number(new FormData(e.target).get('count'))};save()});
app.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.mode){mode=b.dataset.mode;render()}if(b.dataset.zoom){zoom=Math.min(1.6,Math.max(1,zoom+Number(b.dataset.zoom)*.2));render()}if(b.dataset.step){let stage=Number(b.dataset.step);incident=stage?{...incident,stage}:null;save()}});
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
